import { Check } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { WORK_STAGES, WORK_STAGE_LABEL, type WorkStage } from "@/lib/work-stage";

const REVISION_ONLY_STAGES = new Set<WorkStage>(["needs_revision", "pending_rereview"]);

/** Ringkasan visual tahap pekerjaan saat ini — riwayat lengkap (pelaku, waktu, catatan) tetap di ActivityTimeline. */
export function WorkStepper({ current, cancelled, hasEverRequestedRevision }: { current: WorkStage; cancelled?: boolean; hasEverRequestedRevision: boolean }) {
  if (cancelled) return null;
  const currentIndex = WORK_STAGES.indexOf(current);
  return (
    <ol className="flex flex-wrap gap-x-1 gap-y-3" aria-label="Tahap pekerjaan">
      {WORK_STAGES.map((stage, i) => {
        // Tahap revisi dilewati (bukan "sudah selesai") bila pekerjaan ini TIDAK PERNAH direvisi —
        // mencegah dua tahap yang tidak pernah terjadi ditandai seolah sudah dilalui.
        const applicable = !REVISION_ONLY_STAGES.has(stage) || hasEverRequestedRevision;
        const done = i < currentIndex && applicable;
        const active = i === currentIndex;
        return (
          <li key={stage} className="flex items-center">
            <span
              className={cn(
                "flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium whitespace-nowrap",
                active && "bg-accent-soft text-accent ring-1 ring-accent/30",
                done && !active && "text-ink-2",
                !done && !active && "text-ink-3",
              )}
              aria-current={active ? "step" : undefined}
            >
              {done ? <Check className="size-3.5 text-accent" aria-hidden="true" /> : <span className={cn("size-1.5 rounded-full", active ? "bg-accent" : "bg-line")} aria-hidden="true" />}
              {WORK_STAGE_LABEL[stage]}
            </span>
            {i < WORK_STAGES.length - 1 && <span className="mx-1 h-px w-3 bg-line" aria-hidden="true" />}
          </li>
        );
      })}
    </ol>
  );
}
